validator:
function validate(input) {
  const [{ Contacts = [], Calls = [] }] = input;
  const ids = new Set();
  for (const [id, first] of Contacts) {
    if (id === null) return 'Every contact needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Contacts.`;
    ids.add(id);
    if (first === null) return `Contact ${id} needs a first_name.`;
  }
  for (const [contact, type, duration] of Calls) {
    if (!ids.has(contact)) return `Call by contact ${contact}, who is not in Contacts.`;
    if (type !== 'incoming' && type !== 'outgoing') return "type must be 'incoming' or 'outgoing'.";
    if (duration === null || duration < 1 || duration > 86399) return 'duration must be between 1 and 86399 seconds.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const firsts = ['John', 'Jane', 'Alice', 'Michael', 'Emily', 'Bob'];
  const lasts = ['Doe', 'Smith', 'Johnson', 'Brown', 'Davis'];
  const people = small ? Math.floor(rand() * 6) : 500;
  const Contacts = [];
  for (let id = 1; id <= people; id++) Contacts.push([id, pick(firsts), pick(lasts)]);
  // Small cases draw durations from a short list so that ties, including ties for third place, are common.
  const durations = [59, 61, 120, 180, 300, 300, 3600, 3725, 86399];
  const calls = people === 0 ? 0 : small ? Math.floor(rand() * 9) : 2000;
  const Calls = [];
  for (let i = 0; i < calls; i++) {
    Calls.push([1 + Math.floor(rand() * people), rand() < 0.5 ? 'incoming' : 'outgoing', small ? pick(durations) : 1 + Math.floor(rand() * 86399)]);
  }
  return [{ Contacts, Calls }];
}
